"""Offline settings guide, revised from Program/VaporLock_Settings_Guide.html.

Prose is localized; backtick-delimited configuration keys/literals stay intact.
Static browser documents contain no scripts or external resources.
"""
from html import escape
from pathlib import Path

LANGUAGES = ("en", "zh-CN", "de", "ru", "fr")
# Each topic contains (title, prose) in the language order above.
TOPICS = (
    ("start", (
        ("Start here", "Save a copy of your active profile in Profiles. Check capture and detection in Observe only mode, then test one change at a time in the Official Aim Testing Suite or another authorized test environment. If you change several values at once, you cannot tell which change helped.\nUse the controls in Detection, Targeting, and Movement. Advanced profile edits use the configuration keys shown below; reload the edited profile afterward."),
        ("从这里开始", "先在配置页面保存当前配置的副本。以仅观察模式检查捕获与检测，然后在官方瞄准测试套件或其他获准的测试环境中每次只修改一项设置。同时修改多个值，就无法判断哪项改善了效果。\n使用检测、目标选择与移动页面的控件。手动编辑配置时可参考下方的配置键；编辑后重新加载配置。"),
        ("Hier beginnen", "Speichern Sie unter Profile eine Kopie des aktiven Profils. Prüfen Sie Aufnahme und Erkennung im Modus Nur beobachten. Testen Sie dann jeweils eine Änderung in der Official Aim Testing Suite oder einer anderen erlaubten Testumgebung. Mehrere gleichzeitige Änderungen lassen sich nicht einzeln bewerten.\nVerwenden Sie Erkennung, Zielauswahl und Bewegung. Die unten genannten Konfigurationsschlüssel helfen bei manuellen Profiländerungen; laden Sie das bearbeitete Profil anschließend neu."),
        ("Начните здесь", "Сохраните копию текущего профиля в разделе профилей. Проверьте захват и обнаружение в режиме только наблюдения, затем меняйте по одному параметру в Official Aim Testing Suite или другой разрешённой тестовой среде. При нескольких изменениях сразу нельзя понять, какое помогло.\nИспользуйте разделы обнаружения, выбора цели и движения. Ниже указаны ключи для ручного редактирования профиля; после правки загрузите профиль заново."),
        ("Commencer ici", "Enregistrez une copie du profil actif dans Profils. Vérifiez la capture et la détection en mode Observation seule, puis testez une modification à la fois dans l’Official Aim Testing Suite ou un autre environnement de test autorisé. Plusieurs changements simultanés empêchent d’identifier celui qui aide.\nUtilisez Détection, Ciblage et Mouvement. Les clés ci-dessous servent aux modifications manuelles du profil ; rechargez ensuite le profil modifié."),
    )),
    ("setup", (
        ("Setup and calibration", "Run setup & calibration from Overview. Choose a compatible model and processing provider, confirm the capture region, and confirm the activation binding. Applying a preset changes profile values; it never starts capture automatically.\nStart with Observe only. Check the preview, class IDs, target eligibility, and transport diagnostics before enabling movement. Calibrate input scale for the selected transport; a good baseline makes gain and smoothing easier to tune."),
        ("设置与校准", "在概览页面运行设置与校准。选择兼容的模型与处理提供程序，确认捕获区域和激活绑定。应用预设仅修改配置值，不会自动开始捕获。\n先使用仅观察模式。启用移动前检查预览、类别 ID、目标资格和传输诊断。根据所选传输方式校准输入比例；正确的基准有助于调整增益与平滑。"),
        ("Einrichtung und Kalibrierung", "Öffnen Sie Einrichtung und Kalibrierung in der Übersicht. Wählen Sie ein kompatibles Modell und einen Anbieter, prüfen Sie den Aufnahmebereich und bestätigen Sie die Aktivierungsbelegung. Ein Preset ändert nur Profilwerte und startet die Aufnahme nie automatisch.\nBeginnen Sie mit Nur beobachten. Prüfen Sie Vorschau, Klassen-IDs, Zieleignung und Ausgabediagnose, bevor Sie Bewegung aktivieren. Kalibrieren Sie die Eingabeskalierung für den gewählten Transport, bevor Sie Verstärkung und Glättung abstimmen."),
        ("Настройка и калибровка", "Запустите настройку и калибровку из обзора. Выберите совместимую модель и провайдер, проверьте область захвата и подтвердите привязку активации. Пресет меняет значения профиля, но не запускает захват автоматически.\nНачните с режима только наблюдения. Перед включением движения проверьте предпросмотр, ID классов, пригодность цели и диагностику вывода. Откалибруйте масштаб ввода для выбранного транспорта, затем настраивайте усиление и сглаживание."),
        ("Configuration et calibration", "Lancez la configuration et la calibration depuis Vue d’ensemble. Choisissez un modèle et un fournisseur compatibles, vérifiez la zone de capture et confirmez la commande d’activation. Un préréglage modifie les valeurs du profil sans démarrer automatiquement la capture.\nCommencez en Observation seule. Vérifiez l’aperçu, les IDs de classes, l’éligibilité de la cible et le diagnostic de sortie avant d’activer le mouvement. Calibrez l’échelle d’entrée du transport choisi avant d’ajuster le gain et le lissage."),
    )),
    ("order", (
        ("Tuning order", "Verify model, capture, class filter, and output readiness first. Then tune confidence and acquisition radii, input calibration, gain and output limits, smoothing, and finally the anchor. Save a working profile before each substantial change.\nThe values below describe direction and useful small steps, not universal presets. Results depend on your model, capture timing, input scale, and output transport."),
        ("调整顺序", "先确认模型、捕获、类别筛选和输出就绪状态。再调整置信度与获取半径、输入校准、增益与输出限制、平滑，最后调整锚点。每次较大修改前保存可用配置。\n下文说明调整方向与小步调整方法，并非通用预设。结果取决于模型、捕获时序、输入比例与输出传输方式。"),
        ("Reihenfolge der Abstimmung", "Prüfen Sie zuerst Modell, Aufnahme, Klassenfilter und Ausgabebereitschaft. Stimmen Sie dann Konfidenz und Erfassungsradien, Eingabekalibrierung, Verstärkung und Ausgabelimits, Glättung und zuletzt den Anker ab. Speichern Sie vor größeren Änderungen ein funktionierendes Profil.\nDie Beispiele sind kleine Einstellschritte, keine universellen Presets. Das Ergebnis hängt von Modell, Aufnahmetiming, Eingabeskalierung und Transport ab."),
        ("Порядок настройки", "Сначала проверьте модель, захват, фильтр классов и готовность вывода. Затем настройте уверенность и радиусы захвата, калибровку ввода, усиление и ограничения, сглаживание и в конце якорь. Перед существенной правкой сохраняйте рабочий профиль.\nПримеры показывают направление и небольшие шаги, а не универсальные пресеты. Результат зависит от модели, времени захвата, масштаба ввода и транспорта."),
        ("Ordre de réglage", "Vérifiez d’abord le modèle, la capture, le filtre de classes et la disponibilité de la sortie. Réglez ensuite la confiance et les rayons d’acquisition, la calibration d’entrée, le gain et les limites, le lissage, puis l’ancrage. Sauvegardez un profil fonctionnel avant chaque changement important.\nLes exemples indiquent une direction et de petits pas, pas des préréglages universels. Le résultat dépend du modèle, du rythme de capture, de l’échelle d’entrée et du transport."),
    )),
    ("anchor", (
        ("Aim at a different point", "Anchor point (`anchor_mode`) sets the base location. Horizontal offset (`anchor_x`) shifts left for negative values and right for positive values. Vertical offset (`anchor_y`) shifts up for negative values and down for positive values.\nOffsets are relative to the detected box. Try small steps such as `0.05` and watch the anchor in the preview; different models describe different boxes, so a fixed offset does not guarantee a head or chest position."),
        ("瞄准不同位置", "锚点 (`anchor_mode`) 设置基准位置。水平偏移 (`anchor_x`) 为负时左移，为正时右移。垂直偏移 (`anchor_y`) 为负时上移，为正时下移。\n偏移相对于检测框。可每次调整 `0.05` 并观察预览中的锚点；不同模型的检测框不同，固定偏移无法保证对应头部或胸部。"),
        ("Einen anderen Punkt anvisieren", "Der Ankerpunkt (`anchor_mode`) bestimmt die Basis. Horizontaler Versatz (`anchor_x`) verschiebt bei negativen Werten nach links, bei positiven nach rechts. Vertikaler Versatz (`anchor_y`) verschiebt negativ nach oben und positiv nach unten.\nVersätze beziehen sich auf die Erkennungsbox. Testen Sie kleine Schritte wie `0.05` in der Vorschau. Unterschiedliche Modelle liefern unterschiedliche Boxen; ein fester Versatz garantiert keine Kopf- oder Brustposition."),
        ("Изменить точку прицеливания", "Якорь (`anchor_mode`) задаёт основу. Горизонтальное смещение (`anchor_x`) сдвигает влево при отрицательных значениях и вправо при положительных. Вертикальное (`anchor_y`) сдвигает вверх при отрицательных и вниз при положительных.\nСмещения относительны рамке обнаружения. Пробуйте шаги `0.05`, наблюдая якорь в предпросмотре. Разные модели дают разные рамки, поэтому фиксированное смещение не гарантирует попадание в голову или грудь."),
        ("Viser un autre point", "Le point d’ancrage (`anchor_mode`) définit la position de base. Le décalage horizontal (`anchor_x`) déplace vers la gauche si négatif et vers la droite si positif. Le décalage vertical (`anchor_y`) déplace vers le haut si négatif et vers le bas si positif.\nCes décalages sont relatifs au cadre détecté. Testez de petits pas, par exemple `0.05`, dans l’aperçu. Les cadres varient selon le modèle ; un décalage fixe ne garantit pas une position sur la tête ou le torse."),
    )),
    ("slow", (
        ("Movement is too slow", "Check input calibration and the selected transport first. Controller output strength (`virtual_controller_strength`) scales controller output; it is not a universal percentage cap.\nIncrease Assistance gain (`gain`) in small steps, then check Maximum step (`max_step`), Dead zone (`deadzone`), and Output smoothing (`movement_smoothing`). More smoothing adds delay. A higher Maximum output rate (`output_rate`) is not a guaranteed improvement; inspect timing and transport readiness. Acquisition radius (`acquisition_radius`) controls which targets can be acquired, not movement speed."),
        ("移动过慢", "先检查输入校准与传输方式。控制器输出强度 (`virtual_controller_strength`) 缩放控制器输出，并非通用百分比上限。\n小幅提高辅助增益 (`gain`)，再检查最大步长 (`max_step`)、死区 (`deadzone`) 和输出平滑 (`movement_smoothing`)。平滑越强，延迟越大。提高最大输出速率 (`output_rate`) 不保证改善；请查看时序与传输就绪状态。获取半径 (`acquisition_radius`) 决定可获取的目标，不决定移动速度。"),
        ("Bewegung ist zu langsam", "Prüfen Sie zuerst Eingabekalibrierung und Transport. Controller-Ausgabestärke (`virtual_controller_strength`) skaliert die Controllerausgabe und ist keine allgemeine Prozentgrenze.\nErhöhen Sie Assistenzverstärkung (`gain`) schrittweise. Prüfen Sie Maximalschritt (`max_step`), Totzone (`deadzone`) und Ausgabeglättung (`movement_smoothing`). Mehr Glättung verzögert die Reaktion. Eine höhere Maximale Ausgaberate (`output_rate`) garantiert keine Verbesserung; prüfen Sie Timing und Transport. Erfassungsradius (`acquisition_radius`) bestimmt verfügbare Ziele, nicht die Bewegungsgeschwindigkeit."),
        ("Движение слишком медленное", "Сначала проверьте калибровку ввода и транспорт. Сила вывода контроллера (`virtual_controller_strength`) масштабирует вывод контроллера, а не задаёт универсальный процентный предел.\nПостепенно повышайте Усиление помощи (`gain`), затем проверьте максимальный шаг (`max_step`), мёртвую зону (`deadzone`) и сглаживание (`movement_smoothing`). Сглаживание добавляет задержку. Более высокая Максимальная частота вывода (`output_rate`) не гарантирует улучшения; проверьте время обработки и транспорт. Радиус захвата (`acquisition_radius`) определяет доступные цели, а не скорость движения."),
        ("Le mouvement est trop lent", "Vérifiez d’abord la calibration d’entrée et le transport. Force de sortie de la manette (`virtual_controller_strength`) met à l’échelle la sortie du contrôleur ; ce n’est pas une limite universelle en pourcentage.\nAugmentez progressivement Gain d'assistance (`gain`), puis vérifiez le pas maximal (`max_step`), la zone morte (`deadzone`) et le lissage (`movement_smoothing`). Le lissage ajoute du délai. Une Fréquence de sortie maximale (`output_rate`) supérieure ne garantit pas une amélioration ; vérifiez le rythme et le transport. Le rayon d’acquisition (`acquisition_radius`) définit les cibles accessibles, pas la vitesse."),
    )),
    ("overshoot", (
        ("Overshoot or shaking", "For overshoot, verify input calibration first, then reduce gain or Maximum step a little. A linear Response curve (`response_curve`) is a useful baseline. Add smoothing gradually only after the scale and limits are sensible; smoothing can add lag.\nFor shaking near the anchor, try a small Dead zone increase, Anchor stabilization (`anchor_smoothing`), or Reference settle radius (`anchor_settle_radius`). If detection boxes flicker, tune confidence or the model before increasing movement smoothing."),
        ("过冲或抖动", "过冲时先确认输入校准，再小幅降低增益或最大步长。线性响应曲线 (`response_curve`) 可作为基准。比例和限制合理后再逐步增加平滑；平滑会增加延迟。\n锚点附近抖动时，可略增死区、锚点稳定 (`anchor_smoothing`) 或参考点稳定半径 (`anchor_settle_radius`)。检测框闪烁时，先调整置信度或模型，再考虑移动平滑。"),
        ("Überschwingen oder Zittern", "Prüfen Sie beim Überschwingen zuerst die Eingabekalibrierung, dann reduzieren Sie Verstärkung oder Maximalschritt etwas. Eine lineare Antwortkurve (`response_curve`) ist eine gute Basis. Erhöhen Sie Glättung erst schrittweise, wenn Skalierung und Limits passen; sie erhöht die Verzögerung.\nBei Zittern am Anker helfen eventuell eine etwas größere Totzone, Ankerstabilisierung (`anchor_smoothing`) oder Referenz-Beruhigungsradius (`anchor_settle_radius`). Flackern die Boxen, prüfen Sie zuerst Konfidenz oder Modell."),
        ("Перелёт или дрожание", "При перелёте сначала проверьте калибровку ввода, затем немного снизьте усиление или максимальный шаг. Линейная кривая (`response_curve`) подходит как основа. Добавляйте сглаживание постепенно после проверки масштаба и ограничений; оно увеличивает задержку.\nПри дрожании у якоря попробуйте чуть увеличить мёртвую зону, стабилизацию якоря (`anchor_smoothing`) или Радиус стабилизации (`anchor_settle_radius`). Если мигают рамки, сначала настройте уверенность или модель."),
        ("Dépassement ou tremblements", "En cas de dépassement, vérifiez la calibration d’entrée, puis réduisez légèrement le gain ou le pas maximal. Une courbe linéaire (`response_curve`) constitue une base utile. Ajoutez progressivement du lissage après avoir vérifié l’échelle et les limites ; il augmente le délai.\nPrès de l’ancrage, essayez une petite hausse de la zone morte, de la stabilisation (`anchor_smoothing`) ou du Rayon de stabilisation (`anchor_settle_radius`). Si les cadres clignotent, réglez d’abord la confiance ou le modèle."),
    )),
    ("detect", (
        ("Nothing detected or too many detections", "Confirm the model loaded in Model Library and the capture region covers the intended area. Confidence (`confidence`) rejects weak detections: lower it gradually if nothing appears; raise it in small steps such as `0.05` if unwanted objects appear.\nClass filter (`class_filter`) must match the model's class IDs. An empty filter permits all classes; `0` permits only class 0. A wrong filter can hide every detection. Shrink acquisition radii to limit candidate selection without hiding preview detections."),
        ("没有检测或检测过多", "确认模型库已加载模型，且捕获区域覆盖目标区域。置信度 (`confidence`) 排除弱检测：无结果时逐步降低，误检过多时可每次提高 `0.05`。\n类别筛选 (`class_filter`) 必须对应模型的类别 ID。空筛选允许所有类别，`0` 只允许类别 0。错误筛选可能隐藏全部检测。缩小获取半径可限制候选选择，而不隐藏预览检测。"),
        ("Keine oder zu viele Erkennungen", "Prüfen Sie geladenes Modell und Aufnahmebereich. Konfidenz (`confidence`) verwirft schwache Erkennungen: bei leerer Vorschau schrittweise senken, bei unerwünschten Objekten in kleinen Schritten wie `0.05` erhöhen.\nDer Klassenfilter (`class_filter`) muss zu den Modell-IDs passen. Leer erlaubt alle Klassen; `0` nur Klasse 0. Ein falscher Filter kann alles ausblenden. Kleinere Erfassungsradien begrenzen die Zielauswahl, ohne Vorschauerkennungen zu verbergen."),
        ("Нет обнаружений или их слишком много", "Проверьте загрузку модели и область захвата. Уверенность (`confidence`) отбрасывает слабые обнаружения: постепенно снижайте её при пустом результате и повышайте шагами, например `0.05`, при лишних объектах.\nФильтр (`class_filter`) должен соответствовать ID классов модели. Пустой фильтр разрешает все классы; `0` только класс 0. Неверный фильтр может скрыть всё. Уменьшение радиусов захвата ограничивает выбор целей, не скрывая обнаружения в предпросмотре."),
        ("Aucune détection ou trop de détections", "Vérifiez que le modèle est chargé et que la capture couvre la bonne zone. La confiance (`confidence`) élimine les détections faibles : baissez-la progressivement si rien n’apparaît, augmentez-la par petits pas comme `0.05` pour réduire les objets indésirables.\nLe filtre (`class_filter`) doit correspondre aux IDs du modèle. Vide, il autorise toutes les classes ; `0` autorise uniquement la classe 0. Un filtre erroné peut tout masquer. Réduisez les rayons d’acquisition pour limiter le choix des cibles sans masquer les détections de l’aperçu."),
    )),
    ("memory", (
        ("Target switching or lost tracks", "For frequent switching, increase Switching margin (`switching`) or Minimum lock duration (`lock_persistence_ms`) a little. Reducing acquisition radius also limits competing candidates.\nTrack memory and Occlusion grace are measured in milliseconds. Adjust them to retain identity across brief gaps. Lost-track prediction is it supports identity and recovery; a missing or unqualified target does not authorize movement. Occlusion recovery radius limits which nearby same-class target can recover the track."),
        ("目标切换或跟踪丢失", "频繁切换时，可略增切换裕量 (`switching`) 或最短锁定时间 (`lock_persistence_ms`)。缩小获取半径也能减少竞争候选。\n轨迹记忆与遮挡宽限以毫秒计。适当调整可在短暂间隙保留身份。丢失轨迹预测为 Premium 功能，用于身份保留与恢复；丢失或不合格目标不能授权移动。遮挡恢复半径限制可恢复轨迹的附近同类目标。"),
        ("Zielwechsel oder verlorene Spuren", "Erhöhen Sie bei häufigen Wechseln Wechselmarge (`switching`) oder Mindesthaltezeit (`lock_persistence_ms`) etwas. Ein kleinerer Erfassungsradius reduziert konkurrierende Ziele.\nSpurgedächtnis und Verdeckungsfrist werden in Millisekunden angegeben. Sie erhalten die Identität bei kurzen Lücken. Vorhersage verlorener Spuren ist Premium und hilft bei Identität und Wiederherstellung; fehlende oder ungeeignete Ziele erlauben keine Bewegung. Der Wiederherstellungsradius begrenzt die passenden nahen Ziele derselben Klasse."),
        ("Переключение целей или потеря трека", "При частых переключениях немного увеличьте запас переключения (`switching`) или минимальное время удержания (`lock_persistence_ms`). Меньший радиус захвата также уменьшает число конкурентов.\nПамять трека и допуск окклюзии измеряются в миллисекундах и сохраняют идентичность при коротких пропусках. Предсказание потерянного трека — функция Premium для идентичности и восстановления; потерянная или непригодная цель не разрешает движение. Радиус восстановления ограничивает поиск ближайших целей того же класса."),
        ("Changements de cible ou pistes perdues", "Pour limiter les changements fréquents, augmentez un peu la marge (`switching`) ou la durée minimale de verrouillage (`lock_persistence_ms`). Un rayon d’acquisition plus petit réduit aussi les concurrents.\nLa mémoire de piste et le délai d’occlusion se mesurent en millisecondes. Ils maintiennent l’identité pendant de brèves interruptions. La prédiction de piste perdue est Premium : elle aide à conserver et retrouver l’identité ; une cible absente ou non éligible n’autorise pas le mouvement. Le rayon de récupération limite les cibles proches de même classe."),
    )),
    ("activation", (
        ("Activation or output does not work", "Check Observe only mode, Movement enabled, the confirmed activation binding, and a fresh qualified target before changing transport. Hold mode requires the configured input to stay pressed; Toggle mode latches activation until toggled off.\nFor a controller binding, choose the input controller slot and button or trigger in Movement. Input authorization and output transport are separate. Virtual controller output needs its installed and approved component; serial and network devices need the correct connection settings. Check Status & Diagnostics and Movement diagnostics for the actual blocked condition."),
        ("激活或输出无效", "更换传输前，先检查仅观察模式、移动启用状态、已确认的激活绑定以及新鲜合格目标。按住模式需要持续按下绑定输入；切换模式保持激活直到再次切换关闭。\n控制器绑定需在移动页面选择输入控制器槽位与按钮或扳机。输入授权与输出传输相互独立。虚拟控制器输出需要安装并批准组件；串口与网络设备需要正确连接设置。在状态与诊断及移动诊断中查看实际阻止原因。"),
        ("Aktivierung oder Ausgabe funktioniert nicht", "Prüfen Sie Nur beobachten, Bewegung aktivieren, bestätigte Aktivierungsbelegung und ein frisches geeignetes Ziel, bevor Sie den Transport ändern. Halten erfordert gedrückte Eingabe; Umschalten bleibt bis zum erneuten Umschalten aktiv.\nWählen Sie für Controller Slot und Taste oder Trigger unter Bewegung. Eingabeautorisierung und Ausgabetransport sind getrennt. Virtuelle Controllerausgabe benötigt die installierte freigegebene Komponente; serielle und Netzwerkgeräte brauchen passende Verbindungseinstellungen. Status und Diagnose sowie Bewegungsdiagnose nennen die tatsächliche Sperre."),
        ("Не работает активация или вывод", "Перед сменой транспорта проверьте режим только наблюдения, включение движения, подтверждённую привязку и свежую пригодную цель. Режим удержания требует нажатого ввода; режим переключения действует до повторного отключения.\nДля контроллера выберите слот и кнопку или триггер в разделе движения. Разрешение ввода и транспорт вывода независимы. Виртуальному контроллеру нужен установленный разрешённый компонент; последовательным и сетевым устройствам — верные подключения. Причину блокировки смотрите в состоянии и диагностике движения."),
        ("L’activation ou la sortie ne fonctionne pas", "Avant de changer le transport, vérifiez Observation seule, Mouvement activé, la commande confirmée et une cible récente éligible. Le mode Maintenir exige une entrée pressée ; le mode Basculer reste actif jusqu’à sa désactivation.\nPour le contrôleur, sélectionnez son emplacement et son bouton ou sa gâchette dans Mouvement. L’autorisation d’entrée et le transport de sortie sont distincts. Le contrôleur virtuel nécessite son composant installé et approuvé ; les appareils série et réseau doivent être correctement connectés. Consultez les diagnostics pour connaître le blocage réel."),
    )),
    ("events", (
        ("Automatic mouse actions", "The snap-radius action is a Premium mouse action. `event_action_enabled` enables it and the selected mouse button receives the action. `event_action_mode` uses `click` for taps or `hold` for a sustained press; `event_action_cooldown_ms` limits click frequency.\nKeep Requires activation (`event_action_requires_activation`) enabled if actions should follow your Hold or Toggle authorization. Disabling that option changes authorization behavior; Observe only and target eligibility still apply. Turn the action off if you do not want automatic presses."),
        ("自动鼠标操作", "吸附半径操作是 Premium 鼠标功能。`event_action_enabled` 启用功能，由选定鼠标按钮执行。`event_action_mode` 的 `click` 表示点击，`hold` 表示持续按下；`event_action_cooldown_ms` 限制点击频率。\n若操作应遵循按住或切换授权，请启用需要激活 (`event_action_requires_activation`)。关闭会改变授权行为，但仅观察模式与目标资格仍然适用。不需要自动按下时关闭该操作。"),
        ("Automatische Mausaktionen", "Die Snap-Radius-Aktion ist eine Premium-Mausfunktion. `event_action_enabled` aktiviert sie für die ausgewählte Maustaste. `event_action_mode` nutzt `click` für Klicks oder `hold` für dauerhaftes Drücken; `event_action_cooldown_ms` begrenzt Klicks.\nLassen Sie Aktivierung erforderlich (`event_action_requires_activation`) an, wenn Aktionen der Halten- oder Umschaltfreigabe folgen sollen. Ausschalten ändert die Autorisierung; Nur beobachten und Zieleignung gelten weiterhin. Deaktivieren Sie die Aktion, wenn Sie keine automatischen Tastendrücke wünschen."),
        ("Автоматические действия мыши", "Действие в радиусе Snap — функция Premium для выбранной кнопки мыши, включаемая `event_action_enabled`. В `event_action_mode` значение `click` означает щелчки, `hold` — удержание; `event_action_cooldown_ms` ограничивает частоту щелчков.\nОставьте требование активации (`event_action_requires_activation`) включённым, если действия должны следовать удержанию или переключению. Отключение меняет авторизацию, но режим наблюдения и пригодность цели сохраняются. Выключите действие, если автоматические нажатия не нужны."),
        ("Actions automatiques de souris", "L’action dans le rayon Snap est une fonction Premium pour le bouton de souris choisi, activée par `event_action_enabled`. `event_action_mode` utilise `click` pour les clics et `hold` pour maintenir ; `event_action_cooldown_ms` limite la fréquence des clics.\nGardez Activation requise (`event_action_requires_activation`) si les actions doivent suivre votre autorisation Maintenir ou Basculer. La désactiver change l’autorisation, mais Observation seule et l’éligibilité restent applicables. Désactivez l’action si vous ne voulez pas de pressions automatiques."),
    )),
    ("compensation", (
        ("Motion compensation", "Use a saved, measured compensation preset for the intended setup. During an Observe session, open Targeting > Compensation > Calibrate from live estimate. Inspect and save the measured result before enabling compensation. The Calibration shortcut opens setup and calibration, which requires capture to be stopped; it does not start motion compensation calibration.\n`motion_compensation_enabled` controls the feature, `motion_compensation_preset` selects an existing saved preset, and `motion_compensation_strength` scales its correction. A made-up preset name does not provide calibration. Recheck the result after changing input sensitivity or output transport."),
        ("运动补偿", "使用针对当前设置保存并测量的补偿预设。在观察会话中打开目标锁定 > 补偿 > 从实时估计校准。检查并保存测量结果后再启用补偿。校准快捷键打开设置与校准，需要先停止捕获；该快捷键不启动运动补偿校准。\n`motion_compensation_enabled` 控制功能，`motion_compensation_preset` 选择已保存的预设，`motion_compensation_strength` 缩放修正。随意填写预设名称无法完成校准。更改输入灵敏度或输出传输后重新检查结果。"),
        ("Bewegungskompensation", "Verwenden Sie ein gespeichertes, gemessenes Kompensationspreset für Ihre Einrichtung. Öffnen Sie während einer Beobachtungssitzung Zielerfassung > Kompensation > Aus Live-Schätzung kalibrieren. Prüfen und speichern Sie das Ergebnis vor dem Aktivieren. Der Kalibrierungs-Shortcut öffnet Einrichtung und Kalibrierung bei gestoppter Aufnahme, nicht die Bewegungskompensation.\n`motion_compensation_enabled` steuert die Funktion, `motion_compensation_preset` wählt ein vorhandenes Preset und `motion_compensation_strength` skaliert die Korrektur. Ein erfundener Name ersetzt keine Kalibrierung. Prüfen Sie das Ergebnis nach Änderungen an Empfindlichkeit oder Transport erneut."),
        ("Компенсация движения", "Используйте сохранённый измеренный пресет для вашей настройки. Во время сеанса наблюдения откройте Наведение > Компенсация > Калибровать по живой оценке. Проверьте и сохраните результат перед включением. Комбинация калибровки открывает настройку и калибровку при остановленном захвате, а не калибровку компенсации движения.\n`motion_compensation_enabled` управляет функцией, `motion_compensation_preset` выбирает существующий пресет, `motion_compensation_strength` масштабирует коррекцию. Выдуманное имя не заменяет калибровку. Повторно проверьте результат после смены чувствительности или транспорта."),
        ("Compensation du mouvement", "Utilisez un préréglage enregistré et mesuré pour votre configuration. Pendant une session d’observation, ouvrez Ciblage > Compensation > Étalonner depuis l'estimation en direct. Vérifiez et enregistrez le résultat avant d’activer la compensation. Le Raccourci de calibration ouvre la configuration et la calibration lorsque la capture est arrêtée, pas la calibration de compensation.\n`motion_compensation_enabled` contrôle la fonction, `motion_compensation_preset` choisit un préréglage existant et `motion_compensation_strength` met à l’échelle la correction. Un nom inventé ne remplace pas une calibration. Vérifiez à nouveau après un changement de sensibilité ou de transport."),
    )),
    ("diagnostics", (
        ("If the problem remains", "Return to Observe only and inspect the preview and Status & Diagnostics. Separate capture/model/class-filter problems from target eligibility, activation, calibration, and transport readiness. The movement engine cannot correct a missing or unsuitable detection.\nLoad your saved working profile to compare. Keep user models, profiles, and training data when updating. Interface themes and display language change presentation; they do not alter target rules, model results, or output settings."),
        ("问题仍然存在", "回到仅观察模式，检查预览与状态和诊断。区分捕获、模型、类别筛选问题和目标资格、激活、校准、传输就绪问题。移动引擎无法修正缺失或不适用的检测。\n加载保存的可用配置进行比较。更新时保留模型、配置与训练数据。界面主题与语言只改变显示，不改变目标规则、模型结果或输出设置。"),
        ("Wenn das Problem bleibt", "Kehren Sie zu Nur beobachten zurück und prüfen Sie Vorschau sowie Status und Diagnose. Trennen Sie Aufnahme-, Modell- und Filterprobleme von Zieleignung, Aktivierung, Kalibrierung und Transportbereitschaft. Die Bewegungsengine kann fehlende oder ungeeignete Erkennung nicht ausgleichen.\nVergleichen Sie mit dem gespeicherten funktionierenden Profil. Bewahren Sie Modelle, Profile und Trainingsdaten beim Update. Themes und Sprache ändern nur die Darstellung, nicht Zielregeln, Modellergebnisse oder Ausgabe."),
        ("Если проблема сохраняется", "Вернитесь в режим только наблюдения и проверьте предпросмотр и диагностику. Отделите проблемы захвата, модели и фильтра от пригодности цели, активации, калибровки и транспорта. Движок не исправит отсутствующее или неподходящее обнаружение.\nЗагрузите рабочий профиль для сравнения. Сохраняйте модели, профили и обучающие данные при обновлении. Темы и язык меняют отображение, а не правила целей, результаты модели или вывод."),
        ("Si le problème persiste", "Revenez en Observation seule et consultez l’aperçu et les diagnostics. Distinguez les problèmes de capture, modèle et filtre de ceux d’éligibilité, activation, calibration et transport. Le moteur de mouvement ne peut pas corriger une détection absente ou inadaptée.\nComparez avec votre profil fonctionnel sauvegardé. Conservez modèles, profils et données d’entraînement lors des mises à jour. Les thèmes et la langue changent la présentation, pas les règles de ciblage, les résultats ou la sortie."),
    )),
)


def guide_html(language="en", *, text="#edf6ff", muted="#b4bfcd", surface="#080b12", accent="#7dbcf5"):
    index = LANGUAGES.index(language) if language in LANGUAGES else 0
    def prose(value):
        return "".join(f"<code>{escape(part)}</code>" if position % 2 else escape(part)
            for position, part in enumerate(value.split("`")))
    language_links = ' · '.join(f'<a href="VaporLock_Settings_Guide_{code}.html" lang="{code}">{label}</a>' for code, label in zip(LANGUAGES, ('English', '简体中文', 'Deutsch', 'Русский', 'Français')))
    entries = [f'<a href="#{key}">{escape(versions[index][0])}</a>' for key, versions in TOPICS]
    content = '<nav aria-label="Languages">' + language_links + '</nav><h1>' + ('Settings guide', '设置指南', 'Einstellungsleitfaden', 'Руководство по настройкам', 'Guide des réglages')[index] + '</h1><p>' + ' &nbsp;·&nbsp; '.join(entries) + '</p>'
    for key, versions in TOPICS:
        title, body = versions[index]
        content += f'<h2 id="{key}">{escape(title)}</h2>'
        content += "".join(f"<p>{prose(paragraph)}</p>" for paragraph in body.split("\n"))
    return f'''<!doctype html><html lang="{LANGUAGES[index]}"><head><meta charset="utf-8">
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'">
        <title>{('Settings guide', '设置指南', 'Einstellungsleitfaden', 'Руководство по настройкам', 'Guide des réglages')[index]} · Vapor Lock</title>
        <style>body {{ color:{text}; background-color:{surface}; max-width:76ch; margin:3rem auto; padding:0 1.5rem; font:17px/1.65 system-ui,sans-serif; }}
        p {{ margin-top:10px; margin-bottom:18px; }} h2 {{ color:{accent}; margin-top:28px; scroll-margin-top:1rem; }}
        a {{ color:{accent}; text-decoration:underline; }} a:focus-visible {{ outline:2px solid {accent}; outline-offset:4px; }}
        code {{ font-family:Consolas,monospace; color:{text}; overflow-wrap:anywhere; }}
        @media print {{ body {{ color:#17263a; background:white; margin:0; }} h2,a,code {{ color:#17263a; }} }}
        </style></head><body>{content}</body></html>'''


def guide_path(root, language):
    """Select a fixed bundled document; callers cannot supply URLs or paths."""
    code = language if language in LANGUAGES else 'en'
    directory = Path(root).resolve() / 'guides'
    if directory.resolve() != directory:
        raise FileNotFoundError('The bundled settings guide directory is invalid.')
    path = directory / f'VaporLock_Settings_Guide_{code}.html'
    if not path.is_file() or path.is_symlink() or path.resolve().parent != directory:
        raise FileNotFoundError('The bundled settings guide is missing.')
    return path


def write_guides(root):
    directory = Path(root) / 'guides'
    directory.mkdir(parents=True, exist_ok=True)
    for language in LANGUAGES:
        (directory / f'VaporLock_Settings_Guide_{language}.html').write_text(guide_html(language), encoding='utf-8')
